import React, { useState, useEffect } from 'react';
import { User, Car, Invoice } from '../types';
import { LogOut, Users, FileText, Car as CarIcon, ShieldAlert, Search, CheckCircle2, XCircle, Lock, HardDrive, Activity, Settings, Cpu, Database, Wifi, Share2, Smartphone, Copy, QrCode, Info, Globe, SmartphoneNfc, Download, ExternalLink, Mail, UserCheck, ChevronRight, AlertTriangle, RefreshCw, HelpCircle } from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ currentUser, allUsers, allCars, allInvoices, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'users' | 'alerts' | 'system' | 'share'>('overview');
  const [searchTerm, setSearchTerm] = useState('');

  // Correction 404 : On force l'URL sur la racine du domaine
  const getBaseUrl = () => {
    // Supprime tout ce qui après le domaine pour éviter les 404 sur les sous-pages
    return window.location.origin + (window.location.pathname.startsWith('/admin') ? '' : window.location.pathname).replace(/\/$/, "");
  };

  const [customUrl, setCustomUrl] = useState(getBaseUrl());
  const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

  // System Stats State
  const [storageUsage, setStorageUsage] = useState(0);
  const [apiStatus, setApiStatus] = useState<'online' | 'offline'>('online');

  useEffect(() => {
    if (activeTab === 'system') {
        try {
            let total = 0;
            const keys = Object.keys(localStorage);
            for (const key of keys) {
                const value = localStorage.getItem(key);
                if (value) {
                    total += ((value.length + key.length) * 2);
                }
            }
            setStorageUsage(total / 1024 / 1024); // MB
        } catch (e) {
            console.warn("Erreur lecture stockage", e);
            setStorageUsage(0);
        }
        setApiStatus(navigator.onLine ? 'online' : 'offline');
    }
  }, [activeTab]);

  const totalStorage = allInvoices.length * 2.5; 
  const usersRequestingReset = allUsers.filter(u => u.passwordResetRequested);
  const pendingResets = usersRequestingReset.length;

  const renderOverview = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Inscrits</span>
             <Users size={16} className="text-nsp-primary" />
          </div>
          <div className="text-2xl font-bold text-white">{allUsers.length}</div>
          <div className="text-xs text-green-500 mt-1">Clients identifiés</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Documents</span>
             <FileText size={16} className="text-blue-500" />
          </div>
          <div className="text-2xl font-bold text-white">{allInvoices.length}</div>
          <div className="text-xs text-gray-500 mt-1">Total documents</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Parc Auto</span>
             <CarIcon size={16} className="text-yellow-500" />
          </div>
          <div className="text-2xl font-bold text-white">{allCars.length}</div>
          <div className="text-xs text-gray-500 mt-1">Véhicules suivis</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Demandes</span>
             <ShieldAlert size={16} className="text-red-500" />
          </div>
          <div className="text-2xl font-bold text-white">{pendingResets}</div>
          <div className="text-xs text-gray-500 mt-1">Attente validation</div>
        </div>
      </div>

      <div className="bg-gradient-to-br from-red-600/10 to-transparent border border-red-600/20 rounded-2xl p-6 flex items-center gap-4">
          <div className="w-12 h-12 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <UserCheck size={28} />
          </div>
          <div>
              <h3 className="text-white font-bold text-lg">Suivi des Inscriptions</h3>
              <p className="text-gray-400 text-sm">Gestion centralisée des {allUsers.length} comptes clients.</p>
          </div>
      </div>
    </div>
  );

  const renderUsers = () => {
    const filteredUsers = allUsers.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="space-y-6 animate-fade-in pb-10">
            <div className="flex flex-col gap-4">
                <div className="flex items-center justify-between">
                    <h3 className="text-xl font-black text-white flex items-center gap-2">
                        <Users className="text-nsp-primary" /> LISTE DES INSCRITS
                    </h3>
                    <div className="bg-nsp-input text-gray-400 px-3 py-1 rounded-full text-[10px] font-black border border-nsp-border uppercase tracking-widest">
                        {filteredUsers.length} Comptes
                    </div>
                </div>
                <div className="bg-nsp-input p-3 rounded-2xl flex items-center gap-3 border border-nsp-border focus-within:border-nsp-primary transition-all shadow-inner">
                    <Search size={20} className="text-gray-500" />
                    <input 
                        type="text" 
                        placeholder="Rechercher un Nom ou un Email..." 
                        className="bg-transparent text-white placeholder-gray-500 outline-none flex-1 text-sm font-medium"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-3">
                {filteredUsers.length > 0 ? (
                    filteredUsers.map(u => {
                        const userCarsCount = allCars.filter(c => c.ownerId === u.id).length;
                        return (
                            <div key={u.id} className="bg-nsp-card p-4 rounded-3xl border border-nsp-border flex items-center justify-between group hover:border-nsp-primary/50 transition-all hover:bg-white/5">
                                <div className="flex items-center gap-4">
                                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-xl transition-transform group-hover:scale-105 ${u.role === 'admin' ? 'bg-red-600 text-white' : 'bg-nsp-input text-nsp-primary border border-nsp-border'}`}>
                                        {u.name.charAt(0).toUpperCase()}
                                    </div>
                                    <div className="min-w-0">
                                        <div className="flex items-center gap-2">
                                            <h4 className="text-white font-black text-base truncate uppercase tracking-tight">{u.name}</h4>
                                            {u.role === 'admin' && <span className="text-[8px] bg-red-600 text-white px-2 py-0.5 rounded-full uppercase font-black">Staff Admin</span>}
                                        </div>
                                        <div className="flex items-center gap-2 text-gray-500 mt-0.5">
                                            <Mail size={12} className="shrink-0" />
                                            <p className="text-xs truncate font-mono text-nsp-primary">{u.email}</p>
                                        </div>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <div className="hidden sm:flex flex-col items-end mr-6">
                                        <span className="text-[9px] text-gray-500 uppercase font-black tracking-widest">Garage</span>
                                        <span className="text-white font-black text-sm">{userCarsCount} voiture(s)</span>
                                    </div>

                                    <button 
                                        onClick={() => { navigator.clipboard.writeText(u.email); alert('Email copié !'); }}
                                        className="p-3 bg-nsp-input text-gray-400 hover:text-white rounded-2xl border border-nsp-border hover:bg-nsp-primary transition-all shadow-lg"
                                        title="Copier l'email"
                                    >
                                        <Copy size={18} />
                                    </button>
                                </div>
                            </div>
                        );
                    })
                ) : (
                    <div className="py-20 text-center flex flex-col items-center justify-center bg-nsp-card rounded-3xl border border-dashed border-nsp-border">
                        <Users size={48} className="text-gray-800 mb-4" />
                        <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Aucun client trouvé</p>
                    </div>
                )}
            </div>
        </div>
    );
  };

  const renderAlerts = () => (
    <div className="space-y-4 animate-fade-in">
      <div className="bg-nsp-card border border-nsp-border rounded-2xl p-6">
         <h3 className="text-white font-bold mb-4 flex items-center gap-2">
           <Lock size={18} className="text-nsp-warning" /> Sécurité des Comptes ({pendingResets})
         </h3>
         <div className="space-y-4">
            {pendingResets === 0 ? (
                <div className="py-12 text-center">
                    <CheckCircle2 size={48} className="text-green-500/20 mx-auto mb-4" />
                    <p className="text-sm text-gray-500 italic">Aucune demande de réinitialisation.</p>
                </div>
            ) : (
                usersRequestingReset.map(u => (
                    <div key={u.id} className="bg-nsp-input p-5 rounded-2xl flex flex-col gap-4 border border-nsp-border">
                       <div className="flex justify-between items-start">
                         <div>
                            <span className="text-white font-black text-sm uppercase">Oubli de Mot de Passe</span>
                            <p className="text-xs text-nsp-primary font-mono mt-1">{u.email}</p>
                         </div>
                         <span className="text-[10px] bg-red-600/20 text-red-500 px-2 py-1 rounded uppercase font-black">Urgent</span>
                       </div>
                       <div className="flex gap-3">
                         <button onClick={() => alert(`Lien envoyé à ${u.email}`)} className="flex-1 bg-green-600 text-white text-xs font-black py-3 rounded-xl shadow-lg shadow-green-900/20 uppercase tracking-widest">Valider</button>
                         <button onClick={() => alert("Refusé")} className="flex-1 bg-red-950/40 text-red-500 text-xs font-black py-3 rounded-xl border border-red-800/30 uppercase tracking-widest">Refuser</button>
                       </div>
                    </div>
                ))
            )}
         </div>
      </div>
    </div>
  );

  const renderSystem = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="bg-nsp-card border border-nsp-border rounded-2xl p-6">
            <h3 className="text-white font-bold mb-6 flex items-center gap-2">
                <Cpu size={20} className="text-nsp-primary" /> État du Serveur Local
            </h3>

            <div className="space-y-6">
                <div className="flex items-center justify-between pb-4 border-b border-nsp-border">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-nsp-input rounded-2xl shadow-inner"><Wifi size={20} className={apiStatus === 'online' ? "text-green-500" : "text-red-500"} /></div>
                        <div>
                            <p className="text-white font-bold text-sm">Internet</p>
                            <p className="text-[10px] text-gray-500 uppercase tracking-wider">{apiStatus === 'online' ? 'Connecté' : 'Mode Offline'}</p>
                        </div>
                    </div>
                    <div className={`px-3 py-1 rounded-lg text-[10px] font-black ${apiStatus === 'online' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'}`}>
                        {apiStatus === 'online' ? 'ACTIF' : 'COUPÉ'}
                    </div>
                </div>

                <div className="flex items-center justify-between pb-4 border-b border-nsp-border">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-nsp-input rounded-2xl shadow-inner"><Database size={20} className="text-blue-500" /></div>
                        <div>
                            <p className="text-white font-bold text-sm">Base de Données</p>
                            <p className="text-[10px] text-gray-500 uppercase tracking-wider">Stockage navigateur</p>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className="text-white font-black text-sm">{storageUsage.toFixed(2)} MB</p>
                    </div>
                </div>
            </div>
        </div>

        <button 
            onClick={() => { if(confirm('⚠️ Vider la base ? Les clients ne pourront plus se connecter.')) { localStorage.clear(); window.location.reload(); } }}
            className="w-full bg-red-950/20 border border-red-600/30 text-red-500 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all hover:bg-red-600 hover:text-white"
        >
            Reset Total des Inscriptions
        </button>
    </div>
  );

  const renderShare = () => {
    // Le QR code suit l'URL personnalisée par l'admin
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(customUrl)}`;

    return (
      <div className="space-y-8 animate-fade-in pb-16">
        <div className="text-center space-y-4">
           <div className="inline-flex items-center justify-center p-5 rounded-[2rem] bg-nsp-primary/10 border border-nsp-primary/20 mb-2">
              <Share2 size={48} className="text-nsp-primary" />
           </div>
           <h3 className="text-3xl font-black text-white tracking-tighter uppercase">Propulser AUTOBOOK</h3>
           <p className="text-gray-400 text-sm max-w-sm mx-auto font-medium">
             Diffusez votre carnet d'entretien numérique à tous vos clients en garage.
           </p>
        </div>

        {/* Configuration de l'URL du QR Code */}
        <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6 shadow-xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-3">
              <HelpCircle size={16} className="text-gray-600" />
           </div>

           <div className="flex items-center justify-between mb-4">
              <h4 className="text-white font-bold text-xs uppercase tracking-widest flex items-center gap-2">
                 <Globe size={14} className="text-blue-400" /> URL racine du QR Code
              </h4>
              {isLocalhost && (
                 <span className="flex items-center gap-1 text-[9px] bg-orange-600/20 text-orange-400 px-2 py-0.5 rounded-full font-black uppercase">
                    <AlertTriangle size={10} /> Mode Local
                 </span>
              )}
           </div>

           <div className="space-y-4">
              <div className="bg-nsp-input p-1 rounded-2xl border border-nsp-border focus-within:border-nsp-primary transition-all flex items-center gap-2">
                 <input 
                    type="text" 
                    value={customUrl}
                    onChange={(e) => setCustomUrl(e.target.value)}
                    placeholder="https://votre-app.vercel.app"
                    className="flex-1 bg-transparent px-4 py-3 text-white text-xs font-mono outline-none"
                 />
                 <button 
                    onClick={() => window.open(customUrl, '_blank')}
                    className="p-3 bg-nsp-card hover:bg-nsp-primary text-gray-400 hover:text-white rounded-xl transition-all flex items-center gap-2"
                    title="Tester le lien"
                 >
                    <span className="text-[10px] font-black uppercase hidden sm:inline">Tester</span>
                    <ExternalLink size={16} />
                 </button>
              </div>

              {/* Guide de résolution 404 */}
              <div className="bg-blue-900/10 border border-blue-500/20 p-4 rounded-2xl">
                 <h5 className="text-blue-400 text-[10px] font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                    <AlertTriangle size={12} /> Solution Anti-404
                 </h5>
                 <p className="text-[10px] text-gray-400 leading-relaxed font-medium">
                    Si vous avez une <strong>Erreur 404</strong> lors du scan : <br/>
                    1. Assurez-vous que l'URL ci-dessus se termine par <strong>votre-site.com</strong> (sans /admin). <br/>
                    2. Si vous testez en local (localhost), le scan ne peut pas fonctionner. <br/>
                    3. Cliquez sur "Tester" : si la page s'ouvre bien sur votre PC, elle s'ouvrira sur le téléphone.
                 </p>
              </div>
           </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">

           {/* QR Code Card */}
           <div className="bg-nsp-card border border-nsp-border rounded-[2.5rem] p-8 flex flex-col items-center shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-nsp-primary via-red-900 to-nsp-primary"></div>

              <h4 className="text-white font-bold text-lg mb-8 flex items-center gap-2 uppercase tracking-[0.2em] text-[10px]">
                 <QrCode size={18} className="text-nsp-primary" /> Scan de déploiement
              </h4>

              <div className="bg-white p-6 rounded-[2rem] shadow-[0_0_60px_rgba(230,57,70,0.3)] mb-8 transition-all group-hover:scale-105 group-hover:rotate-1 duration-500 border-[6px] border-white">
                 <img 
                   src={qrUrl} 
                   alt="QR Code de l'App" 
                   className="w-56 h-56"
                 />
              </div>

              <div className="w-full flex gap-3">
                 <button 
                    onClick={() => window.open(qrUrl, '_blank')}
                    className="flex-1 bg-nsp-input border border-nsp-border text-white text-[10px] font-black py-4 rounded-2xl hover:bg-white hover:text-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"
                 >
                    <Download size={14} /> Image QR
                 </button>
                 <button 
                    onClick={() => { navigator.clipboard.writeText(customUrl); alert('Lien copié !'); }}
                    className="flex-1 bg-nsp-primary text-white text-[10px] font-black py-4 rounded-2xl hover:bg-red-600 transition-all flex items-center justify-center gap-2 shadow-xl shadow-red-900/30 uppercase tracking-widest"
                 >
                    <Copy size={14} /> Copier URL
                 </button>
              </div>
           </div>

           {/* User Journey */}
           <div className="space-y-4">
              <h4 className="text-white font-bold text-xs uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                 <SmartphoneNfc size={16} className="text-nsp-primary" /> Guide client express
              </h4>

              <div className="bg-nsp-card border border-nsp-border p-6 rounded-3xl flex gap-4 items-center">
                 <div className="w-10 h-10 rounded-xl bg-blue-600/10 text-blue-500 flex items-center justify-center font-black shrink-0 shadow-lg">1</div>
                 <p className="text-xs text-gray-300 font-bold">Le client scanne le QR Code (Caméra standard).</p>
              </div>

              <div className="bg-nsp-card border border-nsp-border p-6 rounded-3xl flex gap-4 items-center">
                 <div className="w-10 h-10 rounded-xl bg-nsp-primary/10 text-nsp-primary flex items-center justify-center font-black shrink-0 shadow-lg">2</div>
                 <p className="text-xs text-gray-300 font-bold">Il clique sur "Ajouter à l'écran d'accueil".</p>
              </div>

              <div className="bg-nsp-card border border-nsp-border p-6 rounded-3xl flex gap-4 items-center">
                 <div className="w-10 h-10 rounded-xl bg-green-600/10 text-green-500 flex items-center justify-center font-black shrink-0 shadow-lg">3</div>
                 <p className="text-xs text-gray-300 font-bold">L'icône AUTOBOOK apparaît. Pas de store nécessaire.</p>
              </div>

              <div className="bg-gradient-to-br from-nsp-primary to-red-900 p-8 rounded-[2.5rem] relative overflow-hidden shadow-2xl mt-4">
                 <Sparkles className="absolute -top-2 -right-2 text-white/20" size={80} />
                 <h5 className="text-white font-black text-xs uppercase tracking-[0.2em] mb-4">Secret Tech</h5>
                 <p className="text-xs text-red-100 leading-relaxed font-bold">
                   "Le carnet numérique se transmet comme une carte de visite, mais reste dans la poche du client à vie."
                 </p>
              </div>
           </div>

        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-[#070707] flex flex-col">
      <div className="bg-red-950/40 border-b border-red-900/30 p-6 flex justify-between items-center pt-safe-top backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-4">
           <div className="bg-red-600 p-3 rounded-2xl shadow-xl shadow-red-900/40 transform -rotate-3"><ShieldAlert className="text-white" size={28} /></div>
           <div>
             <h1 className="text-2xl font-black text-white tracking-tighter leading-none uppercase">Admin<span className="text-red-600">Autobook</span></h1>
             <p className="text-red-500 text-[10px] uppercase font-black tracking-[0.3em] mt-1">Console de Distribution NSP</p>
           </div>
        </div>
        <button onClick={onLogout} className="text-white flex items-center gap-2 bg-red-600 hover:bg-red-500 px-5 py-3 rounded-2xl font-black text-[10px] tracking-widest transition-all group shadow-lg shadow-red-900/20">
          QUITTER <LogOut size={16} className="group-hover:translate-x-1 transition-transform" />
        </button>
      </div>

      <div className="flex border-b border-nsp-border px-4 bg-nsp-card/20 overflow-x-auto no-scrollbar backdrop-blur-sm sticky top-[92px] z-40">
        <button onClick={() => setActiveTab('overview')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all whitespace-nowrap uppercase tracking-[0.2em] ${activeTab === 'overview' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}>Synthèse</button>
        <button onClick={() => setActiveTab('users')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all whitespace-nowrap uppercase tracking-[0.2em] ${activeTab === 'users' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}>Utilisateurs Inscrits</button>
        <button onClick={() => setActiveTab('alerts')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all whitespace-nowrap uppercase tracking-[0.2em] ${activeTab === 'alerts' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}>Demandes Reset <span className="bg-red-600 text-white text-[9px] px-1.5 py-0.5 rounded ml-1 font-black">{pendingResets}</span></button>
        <button onClick={() => setActiveTab('system')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all whitespace-nowrap uppercase tracking-[0.2em] ${activeTab === 'system' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}>Espace Stockage</button>
        <button onClick={() => setActiveTab('share')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all whitespace-nowrap uppercase tracking-[0.2em] ${activeTab === 'share' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}>Diffusion 🚀</button>
      </div>

      <div className="flex-1 p-6 overflow-y-auto max-w-6xl mx-auto w-full">
         {activeTab === 'overview' && renderOverview()}
         {activeTab === 'users' && renderUsers()}
         {activeTab === 'alerts' && renderAlerts()}
         {activeTab === 'system' && renderSystem()}
         {activeTab === 'share' && renderShare()}
      </div>
    </div>
  );
};

// Simple Sparkles component for decoration
const Sparkles = ({ className, size }: { className?: string, size: number }) => (
    <svg 
      className={className} 
      width={size} 
      height={size} 
      viewBox="0 0 24 24" 
      fill="none" 
      stroke="currentColor" 
      strokeWidth="2" 
      strokeLinecap="round" 
      strokeLinejoin="round"
    >
      <path d="m12 3 1.912 4.912L18.824 9.824 13.912 11.736 12 16.648 10.088 11.736 5.176 9.824 10.088 7.912 12 3Z" />
      <path d="M5 3v4" /><path d="M3 5h4" /><path d="M21 17v4" /><path d="M19 19h4" />
    </svg>
);

import React, { useState, useEffect } from 'react';
import { User, Car, Invoice } from '../types';
import { LogOut, Users, FileText, Car as CarIcon, ShieldAlert, Search, CheckCircle2, XCircle, Lock, HardDrive, Activity, Settings, Cpu, Database, Wifi, Share2, Smartphone, Copy, QrCode, Info, Globe, SmartphoneNfc, Download, ExternalLink, Mail, UserCheck, ChevronRight, AlertTriangle, RefreshCw, HelpCircle, Zap } from 'lucide-center';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ currentUser, allUsers, allCars, allInvoices, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'users' | 'alerts' | 'system' | 'share'>('overview');
  const [searchTerm, setSearchTerm] = useState('');

  // Correction 404 & Vercel : On récupère l'URL propre
  const getCleanProductionUrl = () => {
    // Force la racine du domaine pour éviter les 404
    return window.location.origin;
  };

  const [customUrl, setCustomUrl] = useState(getCleanProductionUrl());
  const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
  const isVercel = window.location.hostname.includes('vercel.app');

  // System Stats State
  const [storageUsage, setStorageUsage] = useState(0);
  const [apiStatus, setApiStatus] = useState<'online' | 'offline'>('online');

  useEffect(() => {
    if (activeTab === 'system') {
        try {
            let total = 0;
            const keys = Object.keys(localStorage);
            for (const key of keys) {
                const value = localStorage.getItem(key);
                if (value) {
                    total += ((value.length + key.length) * 2);
                }
            }
            setStorageUsage(total / 1024 / 1024); // MB
        } catch (e) {
            console.warn("Erreur lecture stockage", e);
            setStorageUsage(0);
        }
        setApiStatus(navigator.onLine ? 'online' : 'offline');
    }
  }, [activeTab]);

  const usersRequestingReset = allUsers.filter(u => u.passwordResetRequested);
  const pendingResets = usersRequestingReset.length;

  const renderOverview = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Inscrits</span>
             <Users size={16} className="text-nsp-primary" />
          </div>
          <div className="text-2xl font-bold text-white">{allUsers.length}</div>
          <div className="text-xs text-green-500 mt-1">Clients actifs</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Docs IA</span>
             <FileText size={16} className="text-blue-500" />
          </div>
          <div className="text-2xl font-bold text-white">{allInvoices.length}</div>
          <div className="text-xs text-gray-500 mt-1">Factures analysées</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Parc</span>
             <CarIcon size={16} className="text-yellow-500" />
          </div>
          <div className="text-2xl font-bold text-white">{allCars.length}</div>
          <div className="text-xs text-gray-500 mt-1">Véhicules</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Alertes</span>
             <ShieldAlert size={16} className="text-red-500" />
          </div>
          <div className="text-2xl font-bold text-white">{pendingResets}</div>
          <div className="text-xs text-gray-500 mt-1">Actions en attente</div>
        </div>
      </div>

      <div className="bg-nsp-card border border-nsp-border rounded-2xl p-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-nsp-primary/20 rounded-xl flex items-center justify-center text-nsp-primary">
                  <Zap size={24} />
              </div>
              <div>
                  <h3 className="text-white font-bold">État du Déploiement</h3>
                  <p className="text-xs text-gray-500">
                    {isVercel ? "Application en ligne sur Vercel 🚀" : "Application en test local 🛠️"}
                  </p>
              </div>
          </div>
          <div className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${isVercel ? 'bg-green-600/20 text-green-500 border border-green-500/30' : 'bg-orange-600/20 text-orange-500 border border-orange-500/30'}`}>
            {isVercel ? "Mode Production" : "Mode Développement"}
          </div>
      </div>
    </div>
  );

  const renderUsers = () => {
    const filteredUsers = allUsers.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="space-y-6 animate-fade-in pb-10">
            <div className="flex flex-col gap-4">
                <div className="flex items-center justify-between">
                    <h3 className="text-xl font-black text-white flex items-center gap-2">
                        <Users className="text-nsp-primary" /> BASE CLIENTS
                    </h3>
                    <div className="bg-nsp-input text-gray-400 px-3 py-1 rounded-full text-[10px] font-black border border-nsp-border uppercase tracking-widest">
                        {filteredUsers.length} Inscrits
                    </div>
                </div>
                <div className="bg-nsp-input p-3 rounded-2xl flex items-center gap-3 border border-nsp-border focus-within:border-nsp-primary transition-all">
                    <Search size={20} className="text-gray-500" />
                    <input 
                        type="text" 
                        placeholder="Chercher un Nom ou Email..." 
                        className="bg-transparent text-white placeholder-gray-500 outline-none flex-1 text-sm font-medium"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-3">
                {filteredUsers.length > 0 ? (
                    filteredUsers.map(u => (
                        <div key={u.id} className="bg-nsp-card p-4 rounded-3xl border border-nsp-border flex items-center justify-between group hover:border-nsp-primary/50 transition-all">
                            <div className="flex items-center gap-4">
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-xl ${u.role === 'admin' ? 'bg-red-600 text-white' : 'bg-nsp-input text-nsp-primary border border-nsp-border'}`}>
                                    {u.name.charAt(0).toUpperCase()}
                                </div>
                                <div className="min-w-0">
                                    <h4 className="text-white font-black text-base truncate uppercase tracking-tight">{u.name}</h4>
                                    <div className="flex items-center gap-2 text-gray-500 mt-0.5">
                                        <Mail size={12} className="shrink-0" />
                                        <p className="text-xs truncate font-mono text-nsp-primary">{u.email}</p>
                                    </div>
                                </div>
                            </div>
                            <button 
                                onClick={() => { navigator.clipboard.writeText(u.email); alert('Email copié !'); }}
                                className="p-3 bg-nsp-input text-gray-400 hover:text-white rounded-2xl border border-nsp-border hover:bg-nsp-primary transition-all shadow-lg"
                            >
                                <Copy size={18} />
                            </button>
                        </div>
                    ))
                ) : (
                    <div className="py-20 text-center flex flex-col items-center justify-center bg-nsp-card rounded-3xl border border-dashed border-nsp-border">
                        <Users size={48} className="text-gray-800 mb-4" />
                        <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">Aucun client trouvé</p>
                    </div>
                )}
            </div>
        </div>
    );
  };

  const renderSystem = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="bg-nsp-card border border-nsp-border rounded-2xl p-6">
            <h3 className="text-white font-bold mb-6 flex items-center gap-2">
                <Cpu size={20} className="text-nsp-primary" /> Données & Stockage
            </h3>

            <div className="space-y-6">
                <div className="flex items-center justify-between pb-4 border-b border-nsp-border">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-nsp-input rounded-2xl shadow-inner"><Database size={20} className="text-blue-500" /></div>
                        <div>
                            <p className="text-white font-bold text-sm">Base de Données</p>
                            <p className="text-[10px] text-gray-500 uppercase tracking-wider">Taille actuelle</p>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className="text-white font-black text-sm">{storageUsage.toFixed(2)} MB</p>
                    </div>
                </div>
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-nsp-input rounded-2xl shadow-inner"><Globe size={20} className="text-purple-500" /></div>
                        <div>
                            <p className="text-white font-bold text-sm">Hébergeur</p>
                            <p className="text-[10px] text-gray-500 uppercase tracking-wider">{isVercel ? 'Vercel Edge' : 'Local Host'}</p>
                        </div>
                    </div>
                    <div className="text-white font-mono text-sm">{isVercel ? 'LIVE' : 'DEV'}</div>
                </div>
            </div>
        </div>
        <button 
            onClick={() => { if(confirm('⚠️ ATTENTION : Effacer tous les clients ?')) { localStorage.clear(); window.location.reload(); } }}
            className="w-full bg-red-950/20 border border-red-600/30 text-red-500 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all hover:bg-red-600 hover:text-white"
        >
            Reset Base de Données
        </button>
    </div>
  );

  const renderShare = () => {
    // QR Code basé sur l'URL racine (anti-404)
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=450x450&data=${encodeURIComponent(customUrl)}`;

    return (
      <div className="space-y-8 animate-fade-in pb-16">
        <div className="text-center space-y-4">
           <div className="inline-flex items-center justify-center p-5 rounded-[2rem] bg-nsp-primary/10 border border-nsp-primary/20 mb-2">
              <Share2 size={48} className="text-nsp-primary" />
           </div>
           <h3 className="text-3xl font-black text-white tracking-tighter uppercase">Diffusion Client</h3>
           <p className="text-gray-400 text-sm max-w-sm mx-auto font-medium">
             Utilisez ce QR Code pour que vos clients installent Autobook sur leur écran d'accueil.
           </p>
        </div>

        {/* Status du Déploiement */}
        <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6 shadow-xl relative overflow-hidden">
           {isVercel && (
             <div className="absolute top-0 right-0 p-3">
                <div className="bg-green-500 w-3 h-3 rounded-full animate-ping"></div>
             </div>
           )}

           <div className="flex items-center justify-between mb-4">
              <h4 className="text-white font-bold text-xs uppercase tracking-widest flex items-center gap-2">
                 <Globe size={14} className="text-blue-400" /> URL de l'Application
              </h4>
              <span className={`flex items-center gap-1 text-[9px] px-2 py-0.5 rounded-full font-black uppercase ${isVercel ? 'bg-green-600/20 text-green-500' : 'bg-orange-600/20 text-orange-500'}`}>
                 {isVercel ? "Vercel Production" : "Test Local"}
              </span>
           </div>

           <div className="space-y-4">
              <div className="bg-nsp-input p-1 rounded-2xl border border-nsp-border focus-within:border-nsp-primary transition-all flex items-center gap-2">
                 <input 
                    type="text" 
                    value={customUrl}
                    onChange={(e) => setCustomUrl(e.target.value)}
                    className="flex-1 bg-transparent px-4 py-3 text-white text-xs font-mono outline-none"
                 />
                 <button 
                    onClick={() => { navigator.clipboard.writeText(customUrl); alert('Lien copié !'); }}
                    className="p-3 bg-nsp-card hover:bg-nsp-primary text-gray-400 hover:text-white rounded-xl transition-all"
                 >
                    <Copy size={16} />
                 </button>
              </div>

              {!isVercel && (
                 <div className="bg-orange-600/10 border border-orange-600/30 p-4 rounded-2xl flex gap-3">
                    <AlertTriangle size={20} className="text-orange-500 shrink-0" />
                    <p className="text-[10px] text-orange-200 leading-relaxed font-bold uppercase">
                       Mode Local : Pour que le QR Code fonctionne, déployez d'abord sur Vercel.
                    </p>
                 </div>
              )}
           </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">

           {/* QR Code Card */}
           <div className="bg-nsp-card border border-nsp-border rounded-[2.5rem] p-8 flex flex-col items-center shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-nsp-primary via-red-900 to-nsp-primary"></div>

              <h4 className="text-white font-bold text-lg mb-8 flex items-center gap-2 uppercase tracking-[0.2em] text-[10px]">
                 <QrCode size={18} className="text-nsp-primary" /> Scanner pour installer
              </h4>

              <div className="bg-white p-6 rounded-[2rem] shadow-[0_0_60px_rgba(230,57,70,0.3)] mb-8 transition-all group-hover:scale-105 duration-500 border-[6px] border-white">
                 <img 
                   src={qrUrl} 
                   alt="QR Code de l'App" 
                   className="w-56 h-56"
                 />
              </div>

              <div className="w-full flex gap-3">
                 <button 
                    onClick={() => window.open(qrUrl, '_blank')}
                    className="flex-1 bg-nsp-input border border-nsp-border text-white text-[10px] font-black py-4 rounded-2xl hover:bg-white hover:text-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"
                 >
                    <Download size={14} /> Télécharger
                 </button>
                 <button 
                    onClick={() => window.open(customUrl, '_blank')}
                    className="flex-1 bg-nsp-primary text-white text-[10px] font-black py-4 rounded-2xl hover:bg-red-600 transition-all flex items-center justify-center gap-2 shadow-xl shadow-red-900/30 uppercase tracking-widest"
                 >
                    <ExternalLink size={14} /> Tester Lien
                 </button>
              </div>
           </div>

           {/* User Journey */}
           <div className="space-y-4">
              <h4 className="text-white font-bold text-xs uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                 <SmartphoneNfc size={16} className="text-nsp-primary" /> Guide Client
              </h4>

              {[
                { step: "1", text: "Le client scanne le code avec son appareil photo." },
                { step: "2", text: "Il clique sur 'Ajouter à l'écran d'accueil' (Safari/Chrome)." },
                { step: "3", text: "L'application devient une icône sur son téléphone." }
              ].map((item, idx) => (
                <div key={idx} className="bg-nsp-card border border-nsp-border p-6 rounded-3xl flex gap-4 items-center">
                   <div className="w-10 h-10 rounded-xl bg-nsp-primary/10 text-nsp-primary flex items-center justify-center font-black shrink-0 shadow-lg">{item.step}</div>
                   <p className="text-xs text-gray-300 font-bold">{item.text}</p>
                </div>
              ))}

              <div className="bg-gradient-to-br from-nsp-primary to-red-900 p-8 rounded-[2.5rem] relative overflow-hidden shadow-2xl mt-4">
                 <h5 className="text-white font-black text-xs uppercase tracking-[0.2em] mb-4">Pourquoi Vercel ?</h5>
                 <p className="text-xs text-red-100 leading-relaxed font-bold">
                   "Vercel transforme votre code en une véritable URL accessible par vos clients 24h/24 sans aucune maintenance."
                 </p>
              </div>
           </div>

        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-[#070707] flex flex-col">
      <div className="bg-red-950/40 border-b border-red-900/30 p-6 flex justify-between items-center pt-safe-top backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-4">
           <div className="bg-red-600 p-3 rounded-2xl shadow-xl shadow-red-900/40 transform -rotate-3"><ShieldAlert className="text-white" size={28} /></div>
           <div>
             <h1 className="text-2xl font-black text-white tracking-tighter leading-none uppercase">Admin<span className="text-red-600">Panel</span></h1>
             <p className="text-red-500 text-[10px] uppercase font-black tracking-[0.3em] mt-1">NSP Service Pneu Toulouse</p>
           </div>
        </div>
        <button onClick={onLogout} className="text-white flex items-center gap-2 bg-red-600 hover:bg-red-500 px-5 py-3 rounded-2xl font-black text-[10px] tracking-widest transition-all group">
          QUITTER <LogOut size={16} />
        </button>
      </div>

      <div className="flex border-b border-nsp-border px-4 bg-nsp-card/20 overflow-x-auto no-scrollbar backdrop-blur-sm sticky top-[92px] z-40">
        <button onClick={() => setActiveTab('overview')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-[0.2em] ${activeTab === 'overview' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}>Synthèse</button>
        <button onClick={() => setActiveTab('users')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-[0.2em] ${activeTab === 'users' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}>Clients Inscrits</button>
        <button onClick={() => setActiveTab('system')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-[0.2em] ${activeTab === 'system' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}>Système</button>
        <button onClick={() => setActiveTab('share')} className={`py-5 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-[0.2em] ${activeTab === 'share' ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}>Diffuser l'App 🚀</button>
      </div>

      <div className="flex-1 p-6 overflow-y-auto max-w-6xl mx-auto w-full">
         {activeTab === 'overview' && renderOverview()}
         {activeTab === 'users' && renderUsers()}
         {activeTab === 'system' && renderSystem()}
         {activeTab === 'share' && renderShare()}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Car, Invoice } from '../types';
import { LogOut, Users, FileText, Car as CarIcon, ShieldAlert, Search, CheckCircle2, XCircle, Lock, HardDrive, Activity, Settings, Cpu, Database, Wifi, Share2, Smartphone, Copy, QrCode, Info, Globe, SmartphoneNfc, Download, ExternalLink, Mail, UserCheck, ChevronRight, AlertTriangle, RefreshCw, HelpCircle, Zap } from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ currentUser, allUsers, allCars, allInvoices, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'users' | 'alerts' | 'system' | 'share'>('overview');
  const [searchTerm, setSearchTerm] = useState('');

  // LOGIQUE DE NETTOYAGE D'URL (ANTI-404)
  const getCleanUrl = () => {
    // On prend l'origine (https://mon-app.vercel.app) et on s'arrête là.
    return window.location.origin;
  };

  const [customUrl, setCustomUrl] = useState(getCleanUrl());
  const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
  const isVercel = window.location.hostname.includes('vercel.app');

  // System Stats State
  const [storageUsage, setStorageUsage] = useState(0);
  const [apiStatus, setApiStatus] = useState<'online' | 'offline'>('online');

  useEffect(() => {
    if (activeTab === 'system') {
        try {
            let total = 0;
            const keys = Object.keys(localStorage);
            for (const key of keys) {
                const value = localStorage.getItem(key);
                if (value) {
                    total += ((value.length + key.length) * 2);
                }
            }
            setStorageUsage(total / 1024 / 1024); // MB
        } catch (e) {
            setStorageUsage(0);
        }
        setApiStatus(navigator.onLine ? 'online' : 'offline');
    }
  }, [activeTab]);

  const usersRequestingReset = allUsers.filter(u => u.passwordResetRequested);
  const pendingResets = usersRequestingReset.length;

  const renderOverview = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Inscrits</span>
             <Users size={16} className="text-nsp-primary" />
          </div>
          <div className="text-2xl font-bold text-white">{allUsers.length}</div>
          <div className="text-xs text-green-500 mt-1">Clients identifiés</div>
        </div>
        <div className="bg-nsp-input p-4 rounded-xl border border-nsp-border">
          <div className="flex items-center justify-between mb-2">
             <span className="text-gray-400 text-xs uppercase tracking-wider">Docs IA</span>
             <FileText size={16} className="text-blue-500" />
          </div>
          <div className="text-2xl font-bold text-white">{allInvoices.length}</div>
          <div className="text-xs text-gray-500 mt-1">Factures archivées</div>
        </div>
      </div>

      <div className="bg-nsp-card border border-nsp-border rounded-2xl p-6 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-nsp-primary/20 rounded-xl flex items-center justify-center text-nsp-primary">
                  <Zap size={24} />
              </div>
              <div>
                  <h3 className="text-white font-bold">Déploiement Vercel</h3>
                  <p className="text-xs text-gray-500">
                    {isVercel ? "Application en production 🚀" : "Test local 🛠️"}
                  </p>
              </div>
          </div>
          <div className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${isVercel ? 'bg-green-600/20 text-green-500 border border-green-500/30' : 'bg-orange-600/20 text-orange-500 border border-orange-500/30'}`}>
            {isVercel ? "Online" : "Dev Mode"}
          </div>
      </div>
    </div>
  );

  const renderUsers = () => {
    const filteredUsers = allUsers.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="bg-nsp-input p-3 rounded-2xl flex items-center gap-3 border border-nsp-border">
                <Search size={20} className="text-gray-500" />
                <input 
                    type="text" 
                    placeholder="Chercher par nom ou email..." 
                    className="bg-transparent text-white outline-none flex-1 text-sm font-medium"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="space-y-3">
                {filteredUsers.map(u => (
