import { Invoice, Car } from '../types';

// Règles fournies par le mécanicien NSP
const RULES = {
  REVISION_KM: 20000,
  REVISION_MONTHS: 12,
  DISTRIBUTION_KM: 150000,
  DISTRIBUTION_YEARS: 6,
  CT_YEARS: 2,
  CT_FIRST_YEARS: 4,
  BRAKES_CHECK_KM: 30000,
  TIRES_CHECK_MONTHS: 6
};

interface MaintenanceStatus {
  status: 'success' | 'warning' | 'critical' | 'neutral';
  message: string;
  nextDeadline: string;
  alerts: string[];
}

export const calculateMaintenanceStatus = (car: Car, invoices: Invoice[]): MaintenanceStatus => {
  const currentKm = invoices.length > 0 ? Math.max(...invoices.map(i => i.km)) : car.initialKm;
  const today = new Date();
  const alerts: string[] = [];

  // 1. ANALYSE RÉVISION
  const lastRevision = invoices
    .filter(i => /révision|vidange|entretien/i.test(i.title))
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  if (lastRevision) {
    const nextRevisionDate = new Date(lastRevision.date);
    nextRevisionDate.setFullYear(nextRevisionDate.getFullYear() + 1);
    const kmSinceRevision = currentKm - lastRevision.km;

    if (kmSinceRevision >= RULES.REVISION_KM || today > nextRevisionDate) {
      alerts.push("RÉVISION DÉPASSÉE");
      return { status: 'critical', message: "Action Immédiate : Vidange et filtres à remplacer.", nextDeadline: 'Urgent', alerts };
    }
    if (kmSinceRevision > 18000) {
      alerts.push("RÉVISION PROCHE");
    }
  }

  // 2. ANALYSE PNEUS & NIVEAUX (Basé sur l'état déclaré et le temps)
  if (car.initialState.tires === 'bad') {
    alerts.push("PNEUS USÉS");
    return { status: 'critical', message: "Sécurité : Vos pneus ont été signalés comme usés lors de l'inscription.", nextDeadline: 'Immédiat', alerts };
  }

  // 3. CONTRÔLE TECHNIQUE
  const nextCTDate = calculateNextCT(car.firstRegistrationDate, invoices);
  const monthsToCT = (nextCTDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24 * 30);

  if (monthsToCT < 0) {
    alerts.push("CT PÉRIMÉ");
    return { status: 'critical', message: "Infraction : Votre Contrôle Technique n'est plus valide.", nextDeadline: 'Passée', alerts };
  }
  if (monthsToCT < 1) {
    alerts.push("CT À FAIRE");
    return { status: 'warning', message: "Attention : Prenez rendez-vous pour le CT avant le mois prochain.", nextDeadline: nextCTDate.toLocaleDateString(), alerts };
  }

  // 4. VÉRIFICATION NIVEAUX (Rappel tous les 2 mois ou 2000km)
  const lastAnyDoc = invoices.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];
  const lastCheckDate = lastAnyDoc ? new Date(lastAnyDoc.date) : new Date(car.firstRegistrationDate);
  const monthsSinceCheck = (today.getTime() - lastCheckDate.getTime()) / (1000 * 60 * 60 * 24 * 30);

  if (monthsSinceCheck > 3) {
    return { status: 'warning', message: "Conseil NSP : Vérifiez votre niveau d'huile et la pression des pneus ce week-end.", nextDeadline: 'Routine', alerts: ['CONTRÔLE NIVEAUX'] };
  }

  return { 
    status: 'success', 
    message: "Votre véhicule est parfaitement suivi. L'IA NSP ne détecte aucune anomalie.",
    nextDeadline: 'RAS',
    alerts: []
  };
};

const calculateNextCT = (firstRegDateStr: string, invoices: Invoice[]): Date => {
  const firstReg = new Date(firstRegDateStr);
  const lastCT = invoices
    .filter(i => /contr[oô]le technique|ct\b|visite technique/i.test(i.title))
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  if (lastCT) {
    const next = new Date(lastCT.date);
    next.setFullYear(next.getFullYear() + 2);
    return next;
  }

  const firstCT = new Date(firstReg);
  firstCT.setFullYear(firstCT.getFullYear() + 4);
  return firstCT;
};

