interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'intelligence' | 'users' | 'alerts' | 'share'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [showPasswords, setShowPasswords] = useState<Record<string, boolean>>({});
  const [isRefreshing, setIsRefreshing] = useState(false);

  // URL pour le QR Code
  const customUrl = window.location.origin;

  // --- LOGIQUE DE STATISTIQUES ---
  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const totalCars = allCars.length;
    const totalRevenue = allInvoices.reduce((acc, inv) => acc + inv.price, 0);

    // Répartition carburant
    const fuelDist = allCars.reduce((acc: any, car) => {
      acc[car.fuelType] = (acc[car.fuelType] || 0) + 1;
      return acc;
    }, {});

    // État de santé du parc
    const healthDist = allCars.reduce((acc: any, car) => {
      const state = car.initialState.engine === 'bad' || car.initialState.tires === 'bad' ? 'critical' : 'good';
      acc[state] = (acc[state] || 0) + 1;
      return acc;
    }, { good: 0, critical: 0 });

    return { totalUsers, totalCars, totalRevenue, fuelDist, healthDist };
  }, [allUsers, allCars, allInvoices]);

  const handleManualRefresh = () => {
    setIsRefreshing(true);
    onRefresh();
    setTimeout(() => setIsRefreshing(false), 800);
  };

  const handleResetPassword = (user: User) => {
    const newPass = Math.random().toString(36).slice(-6).toUpperCase();
    if (confirm(`Générer un mot de passe temporaire pour ${user.name} ?\nNouveau MDP : ${newPass}`)) {
      onUpdateUser({ ...user, password: newPass, passwordResetRequested: false });
      alert(`Mot de passe mis à jour : ${newPass}`);
    }
  };

  const renderKPI = (label: string, value: string | number, icon: React.ReactNode, color: string) => (
    <div className="bg-nsp-card border border-nsp-border p-5 rounded-2xl relative overflow-hidden group">
      <div className={`absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform ${color}`}>{icon}</div>
      <span className="text-gray-500 text-[9px] uppercase font-black tracking-widest block mb-1">{label}</span>
      <div className="text-2xl font-black text-white flex items-baseline gap-2">
        {value}
        <span className="text-[10px] text-green-500 flex items-center"><ArrowUpRight size={10}/> +12%</span>
      </div>
    </div>
  );

  const renderIntelligence = () => (
    <div className="space-y-6 animate-fade-in">
      {/* KPIs Grid */}
      <div className="grid grid-cols-2 gap-4">
        {renderKPI("Chiffre d'Affaires", `${stats.totalRevenue.toLocaleString()}€`, <TrendingUp size={40}/>, "text-green-500")}
        {renderKPI("Panier Moyen", `${(stats.totalRevenue / (allInvoices.length || 1)).toFixed(0)}€`, <Zap size={40}/>, "text-yellow-500")}
        {renderKPI("Taux Fidélisation", "84%", <Users size={40}/>, "text-blue-500")}
        {renderKPI("Alertes Sécurité", stats.healthDist.critical, <AlertTriangle size={40}/>, "text-red-500")}
      </div>

      {/* Health Chart Visualization */}
      <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6">
        <h3 className="text-white font-black text-xs uppercase tracking-widest mb-6 flex items-center gap-2">
          <Activity size={16} className="text-nsp-primary" /> État de Santé du Parc Client
        </h3>
        <div className="flex items-end gap-2 h-32 mb-4">
          <div className="flex-1 bg-green-500/20 border-t-2 border-green-500 rounded-t-lg relative group" style={{ height: '100%' }}>
            <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-[10px] text-green-500 font-black">{stats.healthDist.good}</div>
          </div>
          <div className="flex-1 bg-red-500/20 border-t-2 border-red-500 rounded-t-lg relative group" style={{ height: `${(stats.healthDist.critical / stats.totalCars) * 100}%` }}>
            <div className="absolute -top-6 left-1/2 -translate-x-1/2 text-[10px] text-red-500 font-black">{stats.healthDist.critical}</div>
          </div>
        </div>
        <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-gray-500 px-2">
          <span>Véhicules Sains</span>
          <span>Alertes (Pneus/Freins)</span>
        </div>
      </div>

      {/* Fuel Distribution */}
      <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6">
        <h3 className="text-white font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
          <PieChart size={16} className="text-blue-500" /> Mix Énergétique
        </h3>
        <div className="space-y-3">
          {Object.entries(stats.fuelDist).map(([fuel, count]: any) => (
            <div key={fuel} className="space-y-1">
              <div className="flex justify-between text-[10px] font-bold">
                <span className="text-gray-400 uppercase">{fuel}</span>
                <span className="text-white">{count} ({((count / stats.totalCars) * 100).toFixed(0)}%)</span>
              </div>
