                    <div className="flex gap-2">
                       <button onClick={() => handleResetPassword(u)} className="p-2 bg-nsp-input rounded-lg text-gray-400 hover:text-white"><Key size={14}/></button>
                       <button onClick={() => confirm(`Supprimer ${u.name}?`) && onDeleteUser(u.id)} className="p-2 bg-nsp-input rounded-lg text-gray-600 hover:text-red-500"><UserMinus size={14}/></button>
                    </div>
                 </div>
               </div>
             ))}
           </div>
         )}
         {activeTab === 'alerts' && (
           <div className="bg-red-950/20 border border-red-500/20 p-6 rounded-3xl animate-fade-in">
              <h3 className="text-white font-black text-xs uppercase mb-4 flex items-center gap-2"><AlertTriangle size={16} className="text-red-500" /> Requêtes ({allUsers.filter(u => u.passwordResetRequested).length})</h3>
              {allUsers.filter(u => u.passwordResetRequested).length === 0 ? (
                <p className="text-gray-500 text-xs italic text-center py-10">Aucune demande en attente.</p>
              ) : (
                allUsers.filter(u => u.passwordResetRequested).map(u => (
                  <div key={u.id} className="bg-nsp-card p-4 rounded-xl border border-red-500/30 flex justify-between items-center mb-3">
                    <span className="text-white font-bold text-sm">{u.name}</span>
                    <button onClick={() => handleResetPassword(u)} className="bg-red-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase">Réinitialiser</button>
                  </div>
                ))
              )}
           </div>
         )}
      </div>
    </div>
  );
};

